{
  "item_id": "PRISMA_2020_10a",
  "elements": [
    {
      "element_id": "prisma_2020_10a_e1",
      "status": "PRESENT",
      "chunk_id": "text_11",
      "quote": "The primary outcome was pain during endometrial biopsy or endometrial sampling, measured on a 0-10 compatible visual analogue, numerical rating, or equivalent pain scale, with higher scores indicating worse pain. ... Secondary and supplementary outcomes included binary high-pain outcomes, pain at other procedure-related timepoints, need for additional analgesia, participant satisfaction or willingness to undergo repeat biopsy, procedure failure, and adverse events or complications.",
      "reason": "The manuscript explicitly lists and defines the primary outcome (pain during biopsy on a 0-10 compatible scale) and enumerates secondary and supplementary outcome domains."
    },
    {
      "element_id": "prisma_2020_10a_e2",
      "status": "PARTIAL",
      "chunk_id": "text_10",
      "quote": "For continuous pain outcomes, extraction prioritized pain during biopsy or sampling. When several pain timepoints were available, the closest clearly intra-procedural biopsy or sampling pain timepoint was selected.",
      "reason": "The time frame is specified clearly for the primary outcome (intra-procedural / pain during biopsy) and selection rules for timepoints are given, but explicit measurement windows/timing are not provided for all listed secondary/supplementary outcomes (e.g., exact timing for 'pain at other procedure-related timepoints', 'adverse events' windows are described as inconsistent elsewhere), so coverage of time frame information is incomplete."
    },
    {
      "element_id": "prisma_2020_10a_e3",
      "status": "PRESENT",
      "chunk_id": "text_30",
      "quote": "Several eligible or potentially relevant studies were not included in the primary analysis because they did not meet the prespecified extractability or estimand criteria. ... Trials reporting only medians and ranges were not converted into means and standard deviations for the main result because such conversion would require distributional assumptions. Ordinal verbal rating scale studies were not mixed with continuous VAS or NPRS outcomes.",
      "reason": "The authors state which compatible results were excluded (e.g., medians/ranges, ordinal scales) and therefore indicate whether all compatible results were sought and how incompatible result formats were handled."
    },
    {
      "element_id": "prisma_2020_10a_e4",
      "status": "PRESENT",
